        .IMG_WIDTH (IMG_WIDTH),
        .IMG_HEIGHT(IMG_HEIGHT)
    ) DUT (
        .pclk       (pclk),
        .rst        (rst),
        .red_valid  (red_valid),
        .red_mask   (red_mask),
